INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '世界最長の川として知られる河川はどれか。', NULL, '["アマゾン川","ナイル川","長江","ミシシッピ川","黄河"]', 1, '["ナイル川はアフリカ大陸を流れ、全長約6650kmで世界最長の川とされる(流域面積・水量ではアマゾン川が世界最大)。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・地理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '日本の都道府県のうち、海に面していない内陸県はどれか。', NULL, '["新潟県","長野県","静岡県","富山県","石川県"]', 1, '["長野県は日本で唯一、隣接する都道府県がすべて内陸である県であり、海に面していない。他の選択肢はいずれも海に面している。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・地理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '砂漠気候の特徴として正しいものはどれか。', NULL, '["一年を通して降水量が非常に多い","年降水量が極めて少なく、気温の日較差が大きい","四季の変化がはっきりしている","一年中湿度が高く蒸し暑い","冬に大量の雪が降る"]', 1, '["砂漠気候は年降水量がおおむね250mm未満と極めて少なく、昼夜の気温差(日較差)が大きいことが特徴である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・地理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '次のうち、環太平洋造山帯に含まれる国・地域はどれか。', NULL, '["イギリス","日本","フランス","ドイツ","デンマーク"]', 1, '["環太平洋造山帯は太平洋を取り囲むように連なる地震・火山活動の活発な地帯で、日本列島はこれに含まれる。ヨーロッパ諸国はアルプス・ヒマラヤ造山帯やそれ以外の安定した地域に属する。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・地理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '稲作を中心とし、夏に高温多雨となるモンスーン(季節風)の影響を強く受けるアジアの気候区分はどれか。', NULL, '["ステップ気候","地中海性気候","温暖湿潤気候(モンスーンアジア)","ツンドラ気候","西岸海洋性気候"]', 2, '["東アジア・東南アジア・南アジアの多くは、夏に海から湿った季節風(モンスーン)が吹き込み高温多雨となる温暖湿潤気候(モンスーン気候)にあり、稲作に適している。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・地理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '次のうち、国の政治・行政の中心である首都と、実質的な最大都市(経済の中心)が異なる国の組み合わせとして正しいものはどれか。', NULL, '["日本(東京)","フランス(パリ)","オーストラリア(キャンベラ)","イギリス(ロンドン)","エジプト(カイロ)"]', 2, '["オーストラリアの首都はキャンベラであるが、経済・人口面での最大都市はシドニーであり、首都と最大都市が異なる代表例である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・地理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '石油の産出量が多く、OPEC(石油輸出国機構)の中心的な加盟国が集中する地域はどこか。', NULL, '["北ヨーロッパ","中央アジア","西アジア(中東)","東南アジア","南アメリカ南部"]', 2, '["サウジアラビアやイラン、イラクなど、OPEC加盟国の多くは西アジア(中東)地域に集中しており、世界有数の石油産出地帯となっている。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・地理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '河川の下流部に土砂が堆積してできる、扇を逆さにしたような平らな地形を何というか。', NULL, '["扇状地","三角州","台地","盆地","リアス海岸"]', 1, '["三角州(デルタ)は河口付近で川の流れが遅くなり、運ばれてきた細かい土砂が堆積してできる平らな地形である。扇状地は山地から平地に出る場所にできる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・地理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '次のうち、複数の国にまたがって流れ、国際河川として利用されている川はどれか。', NULL, '["信濃川","ドナウ川","利根川","筑後川","木曽川"]', 1, '["ドナウ川はドイツに源を発し、複数の中央・東ヨーロッパ諸国を流れて黒海に注ぐ国際河川であり、古くから水運や国境の役割を果たしてきた。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・地理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '標準時の基準となる経度0度の線(本初子午線)が通る都市はどこか。', NULL, '["パリ","ロンドン(グリニッジ)","マドリード","ローマ","ベルリン"]', 1, '["本初子午線はイギリスのロンドン郊外にある旧グリニッジ天文台を通る経度0度の線と定められており、世界の標準時(GMT)の基準となっている。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・地理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '聖徳太子が定めたとされる、役人の心構えを示した規範はどれか。', NULL, '["大宝律令","十七条の憲法","御成敗式目","武家諸法度","五箇条の御誓文"]', 1, '["十七条の憲法は604年に聖徳太子が制定したとされ、役人(豪族)の心構えとして「和を以て貴しとなす」などが示されている。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・歴史）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '鎌倉幕府において、将軍を補佐し政治の実権を握った役職はどれか。', NULL, '["関白","太政大臣","執権","管領","老中"]', 2, '["執権は鎌倉幕府における将軍の補佐役であり、北条氏が代々この職を独占して幕府の実権を握った。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・歴史）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '織田信長が商工業を活発にするために行った、市場での税や座の特権を廃止した政策を何というか。', NULL, '["刀狩","太閤検地","楽市・楽座","参勤交代","兵農分離"]', 2, '["楽市・楽座は、座(商工業者の同業組合)の特権や市場での税を廃止し、自由な商業活動を促進した織田信長らの政策である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・歴史）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '江戸幕府が大名を統制するために定めた、参勤交代などを規定した法令はどれか。', NULL, '["武家諸法度","公事方御定書","御成敗式目","禁中並公家諸法度","分国法"]', 0, '["武家諸法度は江戸幕府が大名を統制するために定めた法令で、徳川家光の時代に参勤交代の制度が追加された。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・歴史）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '1868年、江戸幕府が倒れ、天皇を中心とする新政府が樹立された一連の政治変革を何というか。', NULL, '["大化の改新","明治維新","建武の新政","寛政の改革","廃藩置県"]', 1, '["明治維新は江戸幕府が倒れて成立した明治新政府のもとで進められた一連の政治・社会の大改革を指す。廃藩置県はその中の一政策。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・歴史）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '1945年、日本の戦後改革の一環として行われ、地主から農地を買い上げて小作農に安く売り渡した政策を何というか。', NULL, '["財閥解体","農地改革","地租改正","殖産興業","教育基本法制定"]', 1, '["農地改革は戦後、GHQの占領政策の一環として行われ、地主制を解体し多くの自作農を生み出した。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・歴史）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '第一次世界大戦後、国際協調と平和維持を目的として設立された国際機関はどれか。', NULL, '["国際連合","国際連盟","ヨーロッパ連合","世界貿易機関","北大西洋条約機構"]', 1, '["国際連盟は第一次世界大戦後の1920年に発足した国際平和機構である。第二次世界大戦後に設立されたのが国際連合。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・歴史）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '奈良時代に、国家の安定を願って聖武天皇が大仏の造立を命じた寺院はどれか。', NULL, '["法隆寺","東大寺","平等院","金閣寺","延暦寺"]', 1, '["聖武天皇は仏教の力で国家を守ろうと考え、東大寺に大仏(盧舎那仏)を造立させた。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・歴史）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '室町時代に発展し、雪舟によって大成された、墨の濃淡で自然を描く絵画様式はどれか。', NULL, '["大和絵","浮世絵","水墨画","蒔絵","障壁画"]', 2, '["水墨画は墨の濃淡だけで山水や自然を表現する絵画様式で、室町時代に禅僧の雪舟によって日本的な様式として大成された。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・歴史）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '1919年、パリ講和会議において結ばれ、第一次世界大戦の終結とドイツへの巨額の賠償を定めた条約はどれか。', NULL, '["ポーツマス条約","ベルサイユ条約","サンフランシスコ平和条約","下関条約","日米安全保障条約"]', 1, '["ベルサイユ条約は第一次世界大戦の講和条約で、ドイツに対して領土の縮小や巨額の賠償金を課す内容が含まれていた。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・歴史）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '日本国憲法が定める三大原則に含まれないものはどれか。', NULL, '["国民主権","基本的人権の尊重","平和主義","三権分立","象徴天皇制"]', 3, '["日本国憲法の三大原則は「国民主権」「基本的人権の尊重」「平和主義」である。三権分立は統治のしくみとして憲法に定められているが、三大原則そのものには含まれない。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・政治）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '国会・内閣・裁判所が互いに抑制し合い、権力の集中を防ぐしくみを何というか。', NULL, '["二院制","三権分立","議院内閣制","地方自治","普通選挙"]', 1, '["三権分立は立法権(国会)・行政権(内閣)・司法権(裁判所)を分離し、互いに抑制と均衡を保つことで権力の集中や濫用を防ぐしくみである。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・政治）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '日本の内閣総理大臣の指名について正しいものはどれか。', NULL, '["国民の直接選挙によって選ばれる","天皇が任意に任命する","国会議員の中から国会の議決によって指名される","最高裁判所長官が指名する","都道府県知事の投票によって選ばれる"]', 2, '["内閣総理大臣は国会議員の中から国会の議決によって指名され、天皇が任命する(国事行為)。国民が直接選ぶわけではない。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・政治）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '地方自治において、住民が一定数の署名を集めることで条例の制定や改廃を求めることができる権利を何というか。', NULL, '["リコール","住民投票","直接請求権","国民審査","請願権"]', 2, '["直接請求権は住民が一定数以上の署名により、条例の制定・改廃や議会の解散、首長・議員の解職(リコール)などを求めることができる権利である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・政治）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '日本国憲法において、最高裁判所が法律や行政処分が憲法に違反していないかを判断する権限を何というか。', NULL, '["違憲審査権","弾劾裁判権","国政調査権","条約締結権","恩赦権"]', 0, '["違憲審査権(法令審査権)は、法律・命令・処分などが憲法に違反していないかを裁判所が審査する権限であり、最終的な判断を下す最高裁判所は「憲法の番人」と呼ばれる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・政治）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '選挙の基本原則のうち、一定の年齢に達したすべての国民に選挙権を認める原則を何というか。', NULL, '["平等選挙","普通選挙","秘密選挙","直接選挙","間接選挙"]', 1, '["普通選挙は財産や性別などによる制限を設けず、一定年齢以上のすべての国民に選挙権を認める原則である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・政治）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '内閣が国会の信任にもとづいて成立し、国会に対して連帯して責任を負うしくみを何というか。', NULL, '["大統領制","議院内閣制","君主制","直接民主制","連邦制"]', 1, '["議院内閣制は、内閣が国会(特に衆議院)の信任にもとづいて成立し、国会に対して連帯責任を負うしくみであり、日本やイギリスなどが採用している。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・政治）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '国際連合の主要機関のうち、世界の平和と安全の維持に関して最も強い権限を持つ機関はどれか。', NULL, '["総会","安全保障理事会","経済社会理事会","国際司法裁判所","事務局"]', 1, '["安全保障理事会は国際の平和と安全の維持に主要な責任を持ち、常任理事国には拒否権が認められているなど強い権限を有する。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・政治）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '日本国憲法第9条が規定している内容として正しいものはどれか。', NULL, '["国民の教育を受ける権利","戦争の放棄と戦力の不保持","地方自治の本旨","国会の二院制","裁判を受ける権利"]', 1, '["憲法第9条は戦争の放棄、戦力の不保持、交戦権の否認を定めており、日本の平和主義の根幹をなす条文である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・政治）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '国民が政治に対する意見を裁判以外の方法で行政機関などに直接伝えることができる権利を何というか。', NULL, '["請願権","参政権","団結権","黙秘権","財産権"]', 0, '["請願権は国民が国や地方公共団体に対して、政治や行政に関する要望・苦情などを直接申し立てることができる権利である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・政治）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '市場経済において、需要量と供給量が一致する価格を何というか。', NULL, '["公定価格","均衡価格","独占価格","最低価格","統制価格"]', 1, '["均衡価格は市場において需要量と供給量が一致し、価格が安定する点で成立する価格である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・経済）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '一国が一定期間内に生産した財・サービスの付加価値の合計を表す経済指標はどれか。', NULL, '["GDP(国内総生産)","CPI(消費者物価指数)","為替レート","日経平均株価","国債残高"]', 0, '["GDP(国内総生産)は一定期間内にその国内で新たに生産された財・サービスの付加価値の合計であり、経済規模を測る代表的な指標である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・経済）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '中央銀行が景気や物価の安定を目的として行う政策を何というか。', NULL, '["財政政策","金融政策","産業政策","貿易政策","社会保障政策"]', 1, '["金融政策は中央銀行(日本銀行など)が公開市場操作などを通じて通貨量や金利を調整し、景気や物価の安定を図る政策である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・経済）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '需要が供給を上回り、通貨の価値が下がって物価が持続的に上昇する現象を何というか。', NULL, '["デフレーション","インフレーション","スタグフレーション","円高","恐慌"]', 1, '["インフレーションは物価が持続的に上昇し、相対的に通貨の価値が下がる現象である。逆に物価が持続的に下落する現象をデフレーションという。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・経済）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '株式会社において、経営方針や役員の選任などを決定する最高意思決定機関はどれか。', NULL, '["取締役会","監査役会","株主総会","執行役員会","労働組合"]', 2, '["株主総会は株式会社の最高意思決定機関であり、株主が出席して定款の変更や役員の選任、決算の承認などを決定する。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・経済）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '円安が日本経済に与える影響として正しいものはどれか。', NULL, '["輸出企業にとって不利になる","輸入品の価格が下がる","外国からの旅行者が増えやすくなる","円の価値が上がる","日本製品が海外で割高になる"]', 2, '["円安になると外国通貨に対して円の価値が下がるため、外国人にとって日本での買い物や旅行が割安になり、訪日外国人が増えやすくなる。また輸出企業には有利に働く。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・経済）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '政府が税収や公共支出を通じて景気を調整する政策を何というか。', NULL, '["金融政策","財政政策","為替政策","産業政策","雇用政策"]', 1, '["財政政策は政府が税金の徴収や公共事業への支出などを通じて、景気の調整や資源配分を行う政策である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・経済）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '市場において1社のみが供給を行い、価格や供給量を自由に決められる状態を何というか。', NULL, '["寡占","独占","完全競争","自由貿易","保護貿易"]', 1, '["独占は特定の商品・サービスの市場を1つの企業だけが支配している状態を指す。少数の企業が支配する場合は寡占という。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・経済）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '社会保障制度のうち、加入者があらかじめ保険料を納め、病気や失業などのときに給付を受けるしくみを何というか。', NULL, '["公的扶助","社会保険","社会福祉","公衆衛生","生活保護"]', 1, '["社会保険は加入者が保険料を納め、病気・老齢・失業などのリスクに備えて給付を受けるしくみで、医療保険や年金保険、雇用保険などが含まれる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・経済）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '複数の国や地域の間で関税やその他の貿易障壁を撤廃・削減し、自由な貿易を促進する協定を何というか。', NULL, '["FTA(自由貿易協定)","ODA(政府開発援助)","NGO(非政府組織)","GDP(国内総生産)","CSR(企業の社会的責任)"]', 0, '["FTA(自由貿易協定)は、特定の国や地域の間で関税やその他の貿易上の障壁を撤廃・削減し、モノやサービスの自由な取引を促進するために結ばれる協定である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・経済）');
